// Generator and Grid power
// 166: Gen input power (1W, signed)
// 167-168: (skip)
// 169: Grid total power (1W, signed)

msg.baseAddr = 166;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 166,
    quantity: 4  // 166-169
};
return msg;

// Load, PV and Battery power
// 178: Load total power (1W, signed)
// 179-185: (skip)
// 186: PV1 power (1W)
// 187: PV2 power (1W)
// 188: PV3 power (1W)
// 189: PV4 power (1W)
// 190: Battery power (1W, signed)

msg.baseAddr = 178;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 178,
    quantity: 13  // 178-190
};
return msg;

// Build PowerFlowState from multiple Modbus reads.

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    node.warn("PowerFlowState: missing base address");
    return null;
}

// Helper: convert unsigned 16-bit to signed
function toSigned16(val) {
    if (val > 32767) {
        return val - 65536;
    }
    return val;
}

// ---- Store partials ----

// Gen/Grid 166-169
if (baseAddr === 166) {
    const genPower = toSigned16(data[0] || 0);    // 166
    const gridPower = toSigned16(data[3] || 0);   // 169

    flow.set("pfs_part_gen_grid", {
        genPowerW: genPower,
        gridPowerW: gridPower
    });
}

// Load/PV/Batt 178-190
else if (baseAddr === 178) {
    // data[0] = 178: Load power
    // data[8] = 186: PV1 power
    // data[9] = 187: PV2 power
    // data[10] = 188: PV3 power
    // data[11] = 189: PV4 power
    // data[12] = 190: Battery power

    const loadPower = toSigned16(data[0] || 0);   // 178
    const pv1Power = data[8] || 0;                // 186
    const pv2Power = data[9] || 0;                // 187
    const pv3Power = data[10] || 0;               // 188
    const pv4Power = data[11] || 0;               // 189
    const battPower = toSigned16(data[12] || 0);  // 190

    const pvTotal = pv1Power + pv2Power + pv3Power + pv4Power;

    flow.set("pfs_part_load_pv_batt", {
        loadPowerW: loadPower,
        pv1PowerW: pv1Power,
        pv2PowerW: pv2Power,
        pv3PowerW: pv3Power,
        pv4PowerW: pv4Power,
        pvTotalPowerW: pvTotal,
        battPowerW: battPower
    });
}
else {
    return null;
}

// ---- Try to assemble ----

const genGridPart = flow.get("pfs_part_gen_grid");
const loadPvBattPart = flow.get("pfs_part_load_pv_batt");

if (!genGridPart || !loadPvBattPart) {
    return null;
}

const deviceId = msg.deviceId
    || global.get("DEVICE_ID")
    || env.get("DEVICE_ID")
    || "EC100-DEV-001";

const state = {
    kind: "PowerFlowState",
    timestampUtc: new Date().toISOString(),
    version: 1,
    DeviceId: deviceId,

    pv: {
        totalPowerW: loadPvBattPart.pvTotalPowerW,
        mppt: [
            { id: 1, powerW: loadPvBattPart.pv1PowerW },
            { id: 2, powerW: loadPvBattPart.pv2PowerW },
            { id: 3, powerW: loadPvBattPart.pv3PowerW },
            { id: 4, powerW: loadPvBattPart.pv4PowerW }
        ]
    },

    grid: {
        totalPowerW: genGridPart.gridPowerW
    },

    load: {
        totalPowerW: loadPvBattPart.loadPowerW
    },

    battery: {
        powerW: loadPvBattPart.battPowerW
    },

    generator: {
        totalPowerW: genGridPart.genPowerW
    }
};

// Clear partials
flow.set("pfs_part_gen_grid", null);
flow.set("pfs_part_load_pv_batt", null);

flow.set("powerFlowStateSnapshot", state);

msg.payload = state;
msg.state = state;
return msg;

// Only handle messages that came from RPC
if (!msg.rpcResponseTopic) {
    return null;
}

const state = msg.state || msg.payload;

msg.payload = state;
msg.topic = msg.rpcResponseTopic;

return msg;
